/* LineSmart — static game preview pages (site/preview/**, generated by scripts/previews.py).
 * The page is fully readable without JS. With JS this makes the odds tables state-aware using the same geo logic as
 * the app (assets/geo.js): books not legal online in the visitor's state are dimmed and tagged, "best price" is
 * recomputed among legal books only (Florida → Hard Rock Bet only, so no comparison highlight), and the sportsbook
 * offers card comes from LSGeo.offersHTML (Nevada → no BetMGM, etc.). Re-renders on "ls-state-change". */
(function () {
  "use strict";
  const G = () => window.LSGeo;
  function apply() {
    const geo = G(); if (!geo) return;
    const ok = k => !k || k === "espn" || geo.isAvailable(k);
    document.querySelectorAll(".pv [data-book]").forEach(el => {
      const k = el.dataset.book, na = !ok(k);
      el.classList.toggle("na-col", na);
      const tag = el.querySelector(".na-tag"); if (tag) tag.innerHTML = k === "espn" ? "" : geo.naTag(k);
    });
    document.querySelectorAll("table.pv-books tbody tr").forEach(tr => {
      const cells = [...tr.querySelectorAll("td[data-score]")];
      const legal = cells.filter(td => ok(td.dataset.book));
      const best = legal.length > 1 ? Math.max(...legal.map(td => +td.dataset.score)) : null;
      cells.forEach(td => td.classList.toggle("best", best !== null && ok(td.dataset.book) && +td.dataset.score === best));
    });
    const ev = geo.current(), books = [...new Set([...document.querySelectorAll("table.pv-books th[data-book]")].map(th => th.dataset.book))];
    const out = ev && ev.state ? books.filter(k => !ok(k)) : [];
    const note = document.querySelector(".pv-na");
    if (note) {
      const names = out.map(k => (document.querySelector(`table.pv-books th[data-book="${k}"]`)?.firstChild?.textContent || k).trim());
      note.hidden = !out.length;
      note.textContent = out.length ? `${names.join(" and ")} ${out.length > 1 ? "don't" : "doesn't"} run a legal online sportsbook in ${ev.stateName}; ${out.length > 1 ? "their" : "its"} lines are shown for reference only.` : "";
    }
    const slot = document.getElementById("pvOffers"); if (slot) slot.innerHTML = geo.offersHTML("preview");
  }
  function started() {   // the static page can be up to one refresh old: point to the live page once the game starts
    const t = document.querySelector(".pv-match time[datetime]"); if (!t) return;
    const at = Date.parse(t.getAttribute("datetime"));
    if (!(at <= Date.now())) return;
    const live = document.querySelector("a.pv-live"); if (!live || document.querySelector(".pv-started")) return;
    const p = document.createElement("p"); p.className = "pv-started";
    p.innerHTML = `This game has started. <a href="${live.getAttribute("href")}">Go to the live game page</a> for the score and current lines.`;
    document.querySelector(".pv-h1")?.after(p);
  }
  async function init() {
    started();
    if (!G()) return;
    try { await G().ready; } catch (e) {}
    apply();
    window.addEventListener("ls-state-change", apply);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init); else init();
})();
